// Uploaded documents stay in this browser. Binary data is stored in IndexedDB,
// while record metadata remains in the existing ERP localStorage store.
let evidenceBusy=false,evidenceDbPromise=null,pdfLibraryPromise=null,evidenceToken=0,evidenceSelectedId=null,evidencePdf=null,evidenceRenderTask=null,evidenceBlobUrl=null,evidencePage=1,evidenceZoom='fit',evidencePageSerial=0;
const MAX_PDF_BYTES=10*1024*1024,MAX_PDF_COUNT=5;
function evidenceDb(){if(!evidenceDbPromise)evidenceDbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('이 브라우저에서 파일 저장을 사용할 수 없습니다.'));const request=indexedDB.open('fuji-erp-documents-v1',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('pdfs'))request.result.createObjectStore('pdfs',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('브라우저 파일 저장소를 열지 못했습니다.'));request.onblocked=()=>reject(Error('다른 탭의 파일 작업을 마친 후 다시 시도해 주세요.'));}).catch(e=>{evidenceDbPromise=null;throw e;});return evidenceDbPromise;}
async function saveEvidenceBlob(id,file,recordId){const db=await evidenceDb();return new Promise((resolve,reject)=>{const tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').put({id,recordId,blob:file});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(Error('PDF를 저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.'));tx.onabort=()=>reject(Error('PDF 저장이 취소되었습니다.'));});}
async function readEvidenceBlob(id){const db=await evidenceDb();return new Promise((resolve,reject)=>{const tx=db.transaction('pdfs','readonly'),req=tx.objectStore('pdfs').get(id);req.onsuccess=()=>req.result?.blob?resolve(req.result.blob):reject(Error('저장된 PDF를 찾지 못했습니다. 파일을 다시 첨부해 주세요.'));req.onerror=()=>reject(Error('PDF를 불러오지 못했습니다.'));});}
async function removeUnusedEvidenceBlob(id){const db=await evidenceDb();return new Promise((resolve,reject)=>{const tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').delete(id);tx.oncomplete=resolve;tx.onerror=reject;});}
function pdfLibrary(){if(!pdfLibraryPromise)pdfLibraryPromise=import('./assets/pdfjs/pdf.min.mjs').then(pdf=>{pdf.GlobalWorkerOptions.workerSrc=new URL('assets/pdfjs/pdf.worker.min.mjs',document.baseURI).href;return pdf;}).catch(e=>{pdfLibraryPromise=null;throw Error('PDF 미리보기를 준비하지 못했습니다. 페이지를 새로고침해 주세요.');});return pdfLibraryPromise;}
async function loadEvidencePdf(blob){const pdf=await pdfLibrary();let password=false;const base=new URL('assets/pdfjs/',document.baseURI).href;const task=pdf.getDocument({data:new Uint8Array(await blob.arrayBuffer()),cMapUrl:base+'cmaps/',cMapPacked:true,standardFontDataUrl:base+'standard_fonts/',wasmUrl:base+'wasm/',isEvalSupported:false,enableXfa:false});task.onPassword=()=>{password=true;task.destroy();};try{return await task.promise;}catch(e){if(password)throw Error('암호가 설정된 PDF는 첨부할 수 없습니다. 암호를 해제한 파일을 선택해 주세요.');throw Error('PDF 파일을 읽지 못했습니다. 정상적인 PDF인지 확인해 주세요.');}}
function evidenceDocuments(r=draft){if(!r)return [];return [...(r.pdfDocuments||[]),...(r.attachments||[]).filter(a=>a.type==='application/pdf').map((a,i)=>({...a,id:'source-'+i,storage:'asset',pages:a.pages||1}))];}
function evidenceSize(n){return n? n>=1048576?(n/1048576).toFixed(1)+'MB':Math.max(1,Math.round(n/1024))+'KB':'첨부 문서';}
function evidenceFileError(file){if(!/\.pdf$/i.test(file.name))return 'PDF 파일만 첨부할 수 있습니다.';if(file.size===0)return '빈 파일은 첨부할 수 없습니다.';if(file.size>MAX_PDF_BYTES)return 'PDF는 파일당 10MB 이하로 선택해 주세요.';return null;}
function releaseEvidencePreview(){evidenceToken++;evidencePageSerial++;if(evidenceRenderTask){try{evidenceRenderTask.cancel();}catch{}evidenceRenderTask=null;}if(evidencePdf){evidencePdf.destroy().catch(()=>{});evidencePdf=null;}if(evidenceBlobUrl){URL.revokeObjectURL(evidenceBlobUrl);evidenceBlobUrl=null;}}
function renderEvidenceField(preferredId=null){releaseEvidencePreview();$('#evidenceSection')?.remove();if(group!=='documents'||!draft)return;const docs=evidenceDocuments();const section=document.createElement('section');section.className='field full evidence-section';section.id='evidenceSection';section.innerHTML=`<div class="evidence-heading"><div><h4>PDF 증빙서류</h4><p>${readonly?'저장된 증빙 문서를 선택하여 확인하세요.':'계약서·발주서·세금계산서 등 관련 PDF를 첨부하세요.'}</p></div><span>${docs.length} / ${MAX_PDF_COUNT}개</span></div>${!readonly?`<button type="button" id="evidencePicker" class="evidence-drop" ${evidenceBusy?'disabled':''}><span>↥</span><div><strong>${evidenceBusy?'PDF 파일 처리 중…':'PDF 파일 선택 또는 여기에 끌어놓기'}</strong><small>파일당 최대 10MB · 최대 5개 · 이 브라우저에 저장</small></div><b>＋ 첨부</b></button>`:''}<p id="evidenceUploadState" class="evidence-upload-state" role="status">${evidenceBusy?'첨부 파일을 확인하고 있습니다.':''}</p><div class="evidence-list">${docs.length?docs.map(meta=>`<div class="evidence-file"><button type="button" class="evidence-file-open" data-evidence-open="${esc(meta.id)}"><span class="evidence-pdf-icon">PDF</span><span><strong>${esc(meta.name)}</strong><small>${esc(evidenceSize(meta.size))} · ${meta.pages||1}페이지</small></span></button>${!readonly&&meta.storage!=='asset'?`<button type="button" class="evidence-remove" data-evidence-remove="${esc(meta.id)}" aria-label="${esc(meta.name)} 첨부 제거" ${evidenceBusy?'disabled':''}>×</button>`:''}</div>`).join(''):'<div class="evidence-empty">첨부된 PDF 문서가 없습니다.</div>'}</div><div id="evidenceViewer" class="evidence-viewer" hidden><div class="evidence-preview-heading"><strong id="evidencePreviewTitle"></strong><div><a id="evidenceOpenOriginal" target="_blank" rel="noopener">원본 열기 ↗</a><a id="evidenceDownload">다운로드 ↓</a></div></div><div class="evidence-view-tools"><button type="button" id="evidencePrev" aria-label="PDF 이전 페이지">‹</button><span id="evidencePageLabel">—</span><button type="button" id="evidenceNext" aria-label="PDF 다음 페이지">›</button><select id="evidenceZoom" aria-label="PDF 확대 비율"><option value="fit">너비에 맞춤</option><option value="1">100%</option><option value="1.5">150%</option></select></div><p id="evidencePreviewState" class="evidence-preview-state" role="status"></p><div id="evidenceCanvasWrap" class="evidence-canvas-wrap"><canvas id="evidenceCanvas" aria-label="첨부 PDF 페이지 미리보기"></canvas></div></div>`;$('#fieldsForm').append(section);
 if($('#evidencePicker')){const picker=$('#evidencePicker');picker.onclick=()=>{if(!evidenceBusy)$('#evidenceFileInput').click();};picker.ondragover=e=>{e.preventDefault();picker.classList.add('dragover');};picker.ondragleave=()=>picker.classList.remove('dragover');picker.ondrop=e=>{e.preventDefault();picker.classList.remove('dragover');if(!evidenceBusy)uploadEvidenceFiles([...e.dataTransfer.files]);};}
 section.querySelectorAll('[data-evidence-open]').forEach(b=>b.onclick=()=>selectEvidenceFile(b.dataset.evidenceOpen));section.querySelectorAll('[data-evidence-remove]').forEach(b=>b.onclick=()=>{if(evidenceBusy||readonly)return;draft.pdfDocuments=(draft.pdfDocuments||[]).filter(m=>m.id!==b.dataset.evidenceRemove);if(evidenceSelectedId===b.dataset.evidenceRemove)evidenceSelectedId=null;markDirty();renderEvidenceField();toast('첨부 목록에서 제거했습니다. 저장하면 반영됩니다.');});$('#evidencePrev').onclick=()=>{if(evidencePdf&&evidencePage>1){evidencePage--;renderEvidencePage();}};$('#evidenceNext').onclick=()=>{if(evidencePdf&&evidencePage<evidencePdf.numPages){evidencePage++;renderEvidencePage();}};$('#evidenceZoom').onchange=e=>{evidenceZoom=e.target.value;renderEvidencePage();};if(docs.length){const selected=docs.find(m=>m.id===(preferredId||evidenceSelectedId))||docs[0];selectEvidenceFile(selected.id);}}
async function uploadEvidenceFiles(files){if(evidenceBusy||readonly||!draft||!files.length)return;const target=draft,existing=evidenceDocuments(target);if(existing.length+files.length>MAX_PDF_COUNT)return toast('PDF는 한 건에 최대 5개까지 첨부할 수 있습니다.');for(const file of files){const error=evidenceFileError(file);if(error)return toast(error);}evidenceBusy=true;renderEvidenceField();let added=0,lastId=null,failure=null;try{for(const file of files){if((target.pdfDocuments||[]).some(m=>m.name===file.name&&m.size===file.size)){toast(file.name+'은(는) 이미 첨부되어 있습니다.');continue;}if($('#evidenceUploadState'))$('#evidenceUploadState').textContent=file.name+' 확인 중…';const header=new TextDecoder('latin1').decode(await file.slice(0,1024).arrayBuffer());if(!header.includes('%PDF-'))throw Error(file.name+': 올바른 PDF 형식이 아닙니다.');const pdf=await loadEvidencePdf(file);const pages=pdf.numPages;await pdf.destroy();if(draft!==target||readonly)throw Error('편집 중인 건이 변경되었습니다. 파일을 다시 첨부해 주세요.');const id=crypto.randomUUID(),meta={id,name:file.name,size:file.size,pages,type:'application/pdf',storage:'indexeddb',addedAt:new Date().toISOString()};await saveEvidenceBlob(id,file,target.id);target.pdfDocuments=target.pdfDocuments||[];target.pdfDocuments.push(meta);const previousDirty=dirty;dirty=true;if(!storeData()){target.pdfDocuments.pop();dirty=previousDirty;await removeUnusedEvidenceBlob(id);throw Error('첨부 정보를 저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.');}added++;lastId=id;}}catch(e){failure=e.message||'PDF를 첨부하지 못했습니다.';}finally{evidenceBusy=false;$('#evidenceFileInput').value='';if(draft===target){refreshSummary();renderEvidenceField(lastId);if(failure)toast((added?added+'개 첨부 완료. ':'')+failure);else if(added)toast(added+'개 PDF를 첨부했습니다. 건을 저장하면 함께 보관됩니다.');}}}
async function selectEvidenceFile(id){const meta=evidenceDocuments().find(m=>m.id===id);if(!meta)return;releaseEvidencePreview();evidenceSelectedId=id;evidencePage=1;evidenceZoom='fit';const token=evidenceToken;$('#evidenceViewer').hidden=false;$('#evidencePreviewTitle').textContent=meta.name;$('#evidencePreviewState').textContent='PDF를 불러오는 중…';$('#evidenceCanvas').hidden=true;$('#evidenceZoom').value='fit';$('#evidencePrev').disabled=true;$('#evidenceNext').disabled=true;$('#evidenceOpenOriginal').removeAttribute('href');$('#evidenceDownload').removeAttribute('href');document.querySelectorAll('[data-evidence-open]').forEach(b=>b.classList.toggle('selected',b.dataset.evidenceOpen===id));try{let blob;if(meta.storage==='asset'){const url=new URL(meta.url,document.baseURI);if(url.origin!==location.origin)throw Error('첨부 문서 주소를 확인해 주세요.');const response=await fetch(url);if(!response.ok)throw Error('첨부 PDF를 불러오지 못했습니다.');blob=await response.blob();}else blob=await readEvidenceBlob(meta.id);if(token!==evidenceToken)return;evidenceBlobUrl=URL.createObjectURL(blob);$('#evidenceOpenOriginal').href=evidenceBlobUrl;$('#evidenceDownload').href=evidenceBlobUrl;$('#evidenceDownload').download=meta.name;const pdf=await loadEvidencePdf(blob);if(token!==evidenceToken){await pdf.destroy();return;}evidencePdf=pdf;await renderEvidencePage();}catch(e){if(token===evidenceToken&&$('#evidencePreviewState'))$('#evidencePreviewState').textContent=e.message||'PDF 미리보기를 표시하지 못했습니다.';}}
async function renderEvidencePage(){if(!evidencePdf||!$('#evidenceCanvas'))return;const token=evidenceToken,serial=++evidencePageSerial,pdf=evidencePdf,pageNumber=evidencePage,canvas=$('#evidenceCanvas');const previous=evidenceRenderTask;if(previous){try{previous.cancel();await previous.promise;}catch{}if(evidenceRenderTask===previous)evidenceRenderTask=null;}if(token!==evidenceToken||serial!==evidencePageSerial)return;$('#evidencePreviewState').textContent='페이지 표시 중…';$('#evidencePageLabel').textContent=pageNumber+' / '+pdf.numPages+' 페이지';$('#evidencePrev').disabled=pageNumber<=1;$('#evidenceNext').disabled=pageNumber>=pdf.numPages;try{const page=await pdf.getPage(pageNumber);if(token!==evidenceToken||serial!==evidencePageSerial)return;const base=page.getViewport({scale:1}),width=Math.max(180,$('#evidenceCanvasWrap').clientWidth-28),scale=evidenceZoom==='fit'?width/base.width:Number(evidenceZoom),viewport=page.getViewport({scale}),ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.ceil(viewport.width*ratio);canvas.height=Math.ceil(viewport.height*ratio);canvas.style.width=Math.floor(viewport.width)+'px';canvas.style.height=Math.floor(viewport.height)+'px';canvas.hidden=false;const task=page.render({canvasContext:canvas.getContext('2d'),viewport,transform:ratio!==1?[ratio,0,0,ratio,0,0]:null});evidenceRenderTask=task;await task.promise;if(evidenceRenderTask===task)evidenceRenderTask=null;if(token===evidenceToken&&serial===evidencePageSerial)$('#evidencePreviewState').textContent='';}catch(e){if(e.name!=='RenderingCancelledException'&&token===evidenceToken&&serial===evidencePageSerial&&$('#evidencePreviewState'))$('#evidencePreviewState').textContent='이 페이지를 표시하지 못했습니다. 원본 열기로 확인해 주세요.';}}
$('#evidenceFileInput').onchange=e=>{const files=[...e.target.files];e.target.value='';uploadEvidenceFiles(files);};window.addEventListener('beforeunload',releaseEvidencePreview);
